def transform(grid):
    h, w = len(grid), len(grid[0])

    # The solid, nonzero divider lines partition the grid into cells.
    divider_rows = [r for r in range(h) if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    divider_cols = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def ranges(size, dividers):
        result = []
        start = 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < size:
            result.append((start, size))
        return result

    row_ranges = ranges(h, divider_rows)
    col_ranges = ranges(w, divider_cols)
    out = [row[:] for row in grid]

    # Record each cell's color and coordinates relative to that cell.
    cells = {}
    for ri, (r0, r1) in enumerate(row_ranges):
        for ci, (c0, c1) in enumerate(col_ranges):
            pixels = [
                (r - r0, c - c0, grid[r][c])
                for r in range(r0, r1)
                for c in range(c0, c1)
                if grid[r][c] != 0
            ]
            if pixels:
                colors = {p[2] for p in pixels}
                if len(colors) == 1:
                    cells[(ri, ci)] = (colors.pop(), {(r, c) for r, c, _ in pixels})

    # A mirrored pair in one row establishes the reflection rule for that
    # adjacent pair of columns and color. Complete matching one-sided cells.
    for ci in range(len(col_ranges) - 1):
        width = col_ranges[ci][1] - col_ranges[ci][0]
        witnessed_colors = set()

        for ri in range(len(row_ranges)):
            left = cells.get((ri, ci))
            right = cells.get((ri, ci + 1))
            if left and right and left[0] == right[0]:
                reflected = {(r, width - 1 - c) for r, c in left[1]}
                if reflected == right[1]:
                    witnessed_colors.add(left[0])

        for ri in range(len(row_ranges)):
            left = cells.get((ri, ci))
            right = cells.get((ri, ci + 1))

            if left and not right and left[0] in witnessed_colors:
                color, shape = left
                r0, _ = row_ranges[ri]
                c0, _ = col_ranges[ci + 1]
                for r, c in shape:
                    out[r0 + r][c0 + width - 1 - c] = color

            elif right and not left and right[0] in witnessed_colors:
                color, shape = right
                r0, _ = row_ranges[ri]
                c0, _ = col_ranges[ci]
                for r, c in shape:
                    out[r0 + r][c0 + width - 1 - c] = color

    return out
